css:
.c6-mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  height: 100vh;
  background: white;
  z-index: 99;
  display: flex;
  flex-direction: column;
  padding: 120px 40px;
  gap: 30px;
  box-shadow: -10px 0 30px rgba(0,0,0,0.05);
  transition: right 0.5s cubic-bezier(0.23, 1, 0.32, 1);
}
